(2614414, 360211, 61138, '<td valign="top">Great energy. The bird orients the image. Nice control of the sky. Easy to blow out that exposure and lose foreground detail. Nicely done.</td>', 'Great energy. The bird orients the image. Nice control of the sky. Easy to blow out that exposure and lose foreground detail. Nicely done.', '2006-07-12 10:55:58.000000', NULL, 1),
(2614417, 362429, 59470, '<td valign="top">i wish there was a little more in focus, but its still interesting - good shot</td>', 'i wish there was a little more in focus, but its still interesting - good shot', '2006-07-12 10:57:03.000000', NULL, 1),
(2614420, 362437, 61138, '<td valign="top">Incredible depth. This photo pulls at the viewer like gravity. A 9!</td>', 'Incredible depth. This photo pulls at the viewer like gravity. A 9!', '2006-07-12 10:58:09.000000', NULL, 1),
(2614422, 362138, 61138, '<td valign="top">I''m speechless...or textless, I guess.<br/> <br/>Lovely.</td>', 'I''m speechless...or textless, I guess. Lovely.', '2006-07-12 10:58:54.000000', NULL, 1),
(2614423, 361754, 5391, '<td valign="top">Beautiful - this would make a wonderful postcard or a great shot for advertising material.  Gorgeous colors and lines.  10</td>', 'Beautiful - this would make a wonderful postcard or a great shot for advertising material.  Gorgeous colors and lines.  10', '2006-07-12 10:59:11.000000', NULL, 1),
(2614428, 362324, 5391, '<td valign="top">Beautiful shot - the tones work really well to create a haunting image.  10</td>', 'Beautiful shot - the tones work really well to create a haunting image.  10', '2006-07-12 11:01:44.000000', NULL, 1),
(2614429, 362093, 61138, '<td valign="top">Was there any other framing option for the right side? The grass and fence seem to detract from a potentially compelling image. Still very nice.</td>', 'Was there any other framing option for the right side? The grass and fence seem to detract from a potentially compelling image. Still very nice.', '2006-07-12 11:02:09.000000', NULL, 1),
(2614433, 362369, 61138, '<td valign="top">Stunning. Great choice of subject. You''ve picked an ideal time of day (for angle of sunlight, etc) The foreground texture draws the eye to the hard shadow which pulls the viewer further into the image.<br/> <br/>Added to my favorites. A 9!</td>', 'Stunning. Great choice of subject. You''ve picked an ideal time of day (for angle of sunlight, etc) The foreground texture draws the eye to the hard shadow which pulls the viewer further into the image. Added to my favorites. A 9!', '2006-07-12 11:05:22.000000', NULL, 1),
(2614438, 362338, 61138, '<td valign="top">Not sure the Dutch angle helps much. Pretty image, though.</td>', 'Not sure the Dutch angle helps much. Pretty image, though.', '2006-07-12 11:07:37.000000', NULL, 1),
(2614446, 362478, 59470, '<td valign="top">Ha!!  Very clever!  As a golfer I find this hillarious - but my shots like to just sit on the edge instead of actually going in (ha ha).  One critique - the grass looks too real to be the actual grass on the green by a real hole</td>', 'Ha!!  Very clever!  As a golfer I find this hillarious - but my shots like to just sit on the edge instead of actually going in (ha ha).  One critique - the grass looks too real to be the actual grass on the green by a real hole', '2006-07-12 11:09:58.000000', NULL, 1),
(2614452, 361079, 61138, '<td valign="top">This one had me scratching and then tilting my head. Fun stuff.</td>', 'This one had me scratching and then tilting my head. Fun stuff.', '2006-07-12 11:15:14.000000', NULL, 1),
(2614454, 361913, 33947, '<td valign="top">Beautiful golden light and sharp focus. Like softness of background. I like looking eye to eye and UP at the plants...neat perspective.</td>', 'Beautiful golden light and sharp focus. Like softness of background. I like looking eye to eye and UP at the plants...neat perspective.', '2006-07-12 11:15:24.000000', NULL, 1),
