(2614561, 359973, 41008, '<td valign="top">the bottom of the cherry being cut off nearly ruins this for me... otherwise, it''s gorgeous</td>', 'the bottom of the cherry being cut off nearly ruins this for me... otherwise, it''s gorgeous', '2006-07-12 12:12:27.000000', NULL, 1),
(2614571, 361743, 41008, '<td valign="top">DOF is a bit too shallow; it''s tough to tell that the other dark blurs are also floats because the line is also visible and the blue and whit eis washed into one dark grey. With a deeper DOF, this would have probably been more effective.</td>', 'DOF is a bit too shallow; it''s tough to tell that the other dark blurs are also floats because the line is also visible and the blue and whit eis washed into one dark grey. With a deeper DOF, this would have probably been more effective.', '2006-07-12 12:16:04.000000', NULL, 1),
(2614572, 361755, 41008, '<td valign="top">this needs to be sharper and it seems as though you tried to bump up contrast too much as a bit of grain is coming through</td>', 'this needs to be sharper and it seems as though you tried to bump up contrast too much as a bit of grain is coming through', '2006-07-12 12:16:56.000000', NULL, 1),
(2614575, 359764, 41008, '<td valign="top">absolutely wonderful!</td>', 'absolutely wonderful!', '2006-07-12 12:17:27.000000', NULL, 1),
(2614582, 359982, 35602, '<td valign="top">Seems very muddy.  Could try a curves adjustment to get it to have more contrast between darks and lights and midtones.  Composition needs some tweaking.  The image seems lacking in an main interest factor.</td>', 'Seems very muddy.  Could try a curves adjustment to get it to have more contrast between darks and lights and midtones.  Composition needs some tweaking.  The image seems lacking in an main interest factor.', '2006-07-12 12:20:24.000000', NULL, 1),
