INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2614590, 362457, 35602, '<td valign="top">Like the concept.  Contrast of colors is really nice.  Compositionally, it seems to evenly divided between the sky and the hill.  Cuts it in half.</td>', 'Like the concept.  Contrast of colors is really nice.  Compositionally, it seems to evenly divided between the sky and the hill.  Cuts it in half.', '2006-07-12 12:23:17.000000', NULL, 1),
(2614597, 361081, 54778, '<td valign="top">Stunning shot...The colours are amazing..And I love the concept of the pic</td>', 'Stunning shot...The colours are amazing..And I love the concept of the pic', '2006-07-12 12:23:54.000000', NULL, 1),
(2614598, 362081, 61138, '<td valign="top">If this is a real crash scene...you''re incredibly lucky to be there with your camera.<br/> <br/>If it''s a staged crash...you''re incredibly gutsy.<br/> <br/>Great image.</td>', 'If this is a real crash scene...you''re incredibly lucky to be there with your camera. If it''s a staged crash...you''re incredibly gutsy. Great image.', '2006-07-12 12:24:17.000000', NULL, 1),
(2614615, 362428, 35602, '<td valign="top">This is lovely.  Canal definitely leads the eye into the scene.  Think a bit of curves adjustment could have taken this image very far.  7</td>', 'This is lovely.  Canal definitely leads the eye into the scene.  Think a bit of curves adjustment could have taken this image very far.  7', '2006-07-12 12:27:57.000000', NULL, 1),
(2614620, 360994, 35602, '<td valign="top">Very strong lines on this one.  Cropping to focus strictly on the left of the image would have really brought out the lovely slants of the shadows.</td>', 'Very strong lines on this one.  Cropping to focus strictly on the left of the image would have really brought out the lovely slants of the shadows.', '2006-07-12 12:30:21.000000', NULL, 1),
(2614623, 362144, 42100, '<td valign="top">Good use of perspective, lines converge towards a vanishing point.  The motion blur seems to go artisticly with the busy street, but if you have to explain it with the title it lead me to think, that "you" didn''t feel like you used it effectively.  I also like the off centeredness of the street, it gives the photo an interesting balance.  The one glaring negative to this photo is the brightness of that one street lamp it''s just way too overpowering.</td>', 'Good use of perspective, lines converge towards a vanishing point.  The motion blur seems to go artisticly with the busy street, but if you have to explain it with the title it lead me to think, that "you" didn''t feel like you used it effectively.  I also like the off centeredness of the street, it gives the photo an interesting balance.  The one glaring negative to this photo is the brightness of that one street lamp it''s just way too overpowering.', '2006-07-12 12:31:39.000000', NULL, 1),
(2614624, 362374, 35602, '<td valign="top">Details are very soft. Still, the out of focus lines in the background do lead the eye to the crystals.  The more I look at it the better I like it.</td>', 'Details are very soft. Still, the out of focus lines in the background do lead the eye to the crystals.  The more I look at it the better I like it.', '2006-07-12 12:32:08.000000', NULL, 1),
(2614644, 362502, 61138, '<td valign="top">The colours and depth and composition are very nice but there are several obvious blemishes. Is that from a dirty lens?</td>', 'The colours and depth and composition are very nice but there are several obvious blemishes. Is that from a dirty lens?', '2006-07-12 12:38:36.000000', NULL, 1),
(2614649, 362147, 59740, '<td valign="top">Nice patterns and perspective</td>', 'Nice patterns and perspective', '2006-07-12 12:40:25.000000', NULL, 1),
(2614653, 362342, 59740, '<td valign="top">Nice but would be improved without so much plain blue sky.</td>', 'Nice but would be improved without so much plain blue sky.', '2006-07-12 12:41:27.000000', NULL, 1),
(2614654, 362406, 59740, '<td valign="top">I don''t get the perspective connection?</td>', 'I don''t get the perspective connection?', '2006-07-12 12:41:53.000000', NULL, 1),
(2614655, 360325, 61138, '<td valign="top">Is it an eclipse, or just a waning moon?</td>', 'Is it an eclipse, or just a waning moon?', '2006-07-12 12:41:59.000000', NULL, 1),
(2614657, 362397, 59740, '<td valign="top">Not very sharp.</td>', 'Not very sharp.', '2006-07-12 12:42:16.000000', NULL, 1),
(2614664, 360849, 59740, '<td valign="top">Nice picture but where is the perspective?</td>', 'Nice picture but where is the perspective?', '2006-07-12 12:43:34.000000', NULL, 1),
(2614668, 362528, 54778, '<td valign="top">A wow catch</td>', 'A wow catch', '2006-07-12 12:44:09.000000', NULL, 1),
(2614669, 362144, 59740, '<td valign="top">Too blurred but good perspective.</td>', 'Too blurred but good perspective.', '2006-07-12 12:44:22.000000', NULL, 1),
(2614674, 360930, 59740, '<td valign="top">Does not show perspective and the bits of green in the foreground are distracting. Not a satisfying composition to me.</td>', 'Does not show perspective and the bits of green in the foreground are distracting. Not a satisfying composition to me.', '2006-07-12 12:45:35.000000', NULL, 1),
(2614678, 362373, 59740, '<td valign="top">Excellent. It''s too bad that the table is overexposed.</td>', 'Excellent. It''s too bad that the table is overexposed.', '2006-07-12 12:46:49.000000', NULL, 1),
(2614681, 361559, 59740, '<td valign="top">I like this better in its normal rotation.</td>', 'I like this better in its normal rotation.', '2006-07-12 12:48:10.000000', NULL, 1),
(2614684, 362452, 54778, '<td valign="top">The pic is honestly very funny.. trying to be so intense when its so not.. very good angle and sky..</td>', 'The pic is honestly very funny.. trying to be so intense when its so not.. very good angle and sky..', '2006-07-12 12:48:41.000000', NULL, 1),
(2614691, 359764, 59740, '<td valign="top">Great shot.</td>', 'Great shot.', '2006-07-12 12:51:11.000000', NULL, 1),
(2614692, 361207, 42100, '<td valign="top">I like the composition of this, you''ve got the subject fairly well off center.  I also like the point of view of looking at him from his level.  I tend to agree with you that this meets the challenge, but expect some DNMC votes from voters that are looking for diverging and converging lines for this challenge.  I got a lot of those kind of votes in the last perspective challenge.  The exposure seems to be spot on for the background, but with the beaver being the subject maybe a stop or two of extra exposure compensation would help emphasize the beaver and bring out more of his detail.</td>', 'I like the composition of this, you''ve got the subject fairly well off center.  I also like the point of view of looking at him from his level.  I tend to agree with you that this meets the challenge, but expect some DNMC votes from voters that are looking for diverging and converging lines for this challenge.  I got a lot of those kind of votes in the last perspective challenge.  The exposure seems to be spot on for the background, but with the beaver being the subject maybe a stop or two of extra exposure compensation would help emphasize the beaver and bring out more of his detail.', '2006-07-12 12:51:11.000000', NULL, 1),
(2614700, 361991, 59740, '<td valign="top">Clever idea.</td>', 'Clever idea.', '2006-07-12 12:54:36.000000', NULL, 1),
(2614704, 361874, 59740, '<td valign="top">This is nice but the color looks too artificial.</td>', 'This is nice but the color looks too artificial.', '2006-07-12 12:57:14.000000', NULL, 1),
(2614714, 361791, 59740, '<td valign="top">Excellent composition, exposure and colors.</td>', 'Excellent composition, exposure and colors.', '2006-07-12 13:01:39.000000', NULL, 1),
(2614717, 362195, 42808, '<td valign="top">unique curved perspective</td>', 'unique curved perspective', '2006-07-12 13:03:58.000000', NULL, 1),
(2614718, 362093, 59740, '<td valign="top">Good idea but not sharp and left side is overexposed.</td>', 'Good idea but not sharp and left side is overexposed.', '2006-07-12 13:04:22.000000', NULL, 1),
(2614721, 359975, 59740, '<td valign="top">Very good but not very sharp.</td>', 'Very good but not very sharp.', '2006-07-12 13:05:39.000000', NULL, 1),
(2614722, 361432, 42808, '<td valign="top">Would have been good capture if just much lighter to see, great idea though.</td>', 'Would have been good capture if just much lighter to see, great idea though.', '2006-07-12 13:05:47.000000', NULL, 1),
(2614726, 362147, 42100, '<td valign="top">Good use of perspective, the line converge to the exit at the other end.  I like the off centered composition, but I think you went a little too far to the right with the exit end.  If you kept that opening a tiny bit back to the left you would be able to see more of the criss-cross detail on the right side of the bridge also.  That''s all pretty much just opinion about the composition, but less opinion is that support on the right edge, it''s just sort of sticking into photo like a sore thumb.  Good exposure in a tough to expose situation, you captured lots of detail up in those rafters.</td>', 'Good use of perspective, the line converge to the exit at the other end.  I like the off centered composition, but I think you went a little too far to the right with the exit end.  If you kept that opening a tiny bit back to the left you would be able to see more of the criss-cross detail on the right side of the bridge also.  That''s all pretty much just opinion about the composition, but less opinion is that support on the right edge, it''s just sort of sticking into photo like a sore thumb.  Good exposure in a tough to expose situation, you captured lots of detail up in those rafters.', '2006-07-12 13:06:21.000000', NULL, 1),
