INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2615514, 362539, 16402, '<td valign="top">I think straightening this a bit would have helped it.</td>', 'I think straightening this a bit would have helped it.', '2006-07-12 16:52:14.000000', NULL, 1),
(2615523, 362028, 16402, '<td valign="top">It''s not clear to me what he''s being "caught" doing, but I can tell that you got the perspective you were after.</td>', 'It''s not clear to me what he''s being "caught" doing, but I can tell that you got the perspective you were after.', '2006-07-12 16:55:44.000000', NULL, 1),
(2615526, 361554, 43400, '<td valign="top">very dramatic and abstract architectural effect-i really like tonal qualities and sepia tones. there''s a bit of a ripple effect in the upper sky (maybe it''s my monitor) that''s a little distracting--due to enhancements. Also the upper/lower borders gives it a motion-picture quality. Overall its a great image.</td>', 'very dramatic and abstract architectural effect-i really like tonal qualities and sepia tones. there''s a bit of a ripple effect in the upper sky (maybe it''s my monitor) that''s a little distracting--due to enhancements. Also the upper/lower borders gives it a motion-picture quality. Overall its a great image.', '2006-07-12 16:57:07.000000', NULL, 1),
(2615580, 362214, 35947, '<td valign="top">Wonderful job!  Great composition!  10</td>', 'Wonderful job!  Great composition!  10', '2006-07-12 17:15:34.000000', NULL, 1),
(2615583, 361793, 55199, '<td valign="top">Your perspective makes the brickwork look interesting.  :)</td>', 'Your perspective makes the brickwork look interesting.  :)', '2006-07-12 17:16:06.000000', NULL, 1),
(2615585, 361546, 35947, '<td valign="top">Seems more snap-shot''ish.  I''d suggest not cropping off tops of heads</td>', 'Seems more snap-shot''ish.  I''d suggest not cropping off tops of heads', '2006-07-12 17:17:22.000000', NULL, 1),
(2615588, 361603, 56725, '<td valign="top">how cute!</td>', 'how cute!', '2006-07-12 17:19:07.000000', NULL, 1),
