(2617962, 360406, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:03:30.000000', NULL, 1),
(2617963, 362439, 61679, '<td valign="top">You captured some nice detail in the sand at the front of the picture.  However, the brightness of the water and the sky naturally draws my eyes to that area of the image and the focus there is soft.  This image could have been improved if you could have used a smaller apperature to extend the depth of focus.</td>', 'You captured some nice detail in the sand at the front of the picture.  However, the brightness of the water and the sky naturally draws my eyes to that area of the image and the focus there is soft.  This image could have been improved if you could have used a smaller apperature to extend the depth of focus.', '2006-07-13 08:03:52.000000', NULL, 1),
