INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2617974, 361570, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:06:55.000000', NULL, 1),
(2617975, 360872, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:07:22.000000', NULL, 1),
(2617976, 361604, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:07:41.000000', NULL, 1),
(2617978, 361643, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:08:25.000000', NULL, 1),
(2617979, 361157, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:08:39.000000', NULL, 1),
(2617981, 362306, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:09:01.000000', NULL, 1),
(2617982, 361735, 25654, '<td valign="top">Great shot</td>', 'Great shot', '2006-07-13 08:09:39.000000', NULL, 1),
(2617983, 360211, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:10:07.000000', NULL, 1),
(2617985, 361953, 61679, '<td valign="top">The leading lines presented by the shape of the hand and the transition from out of focus to in focus draws my eyes to the far left of the image but the detail visible in the fingers keeps my eyes from actually leaving the picture.  Well done.  However, the hand looks odd with the one finger not being visible.</td>', 'The leading lines presented by the shape of the hand and the transition from out of focus to in focus draws my eyes to the far left of the image but the detail visible in the fingers keeps my eyes from actually leaving the picture.  Well done.  However, the hand looks odd with the one finger not being visible.', '2006-07-13 08:10:27.000000', NULL, 1),
(2617986, 361709, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:10:48.000000', NULL, 1),
(2617989, 361692, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:11:22.000000', NULL, 1),
(2617990, 362093, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:12:25.000000', NULL, 1),
(2617992, 359580, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:13:06.000000', NULL, 1),
(2617995, 359644, 25654, '<td valign="top">nice.10</td>', 'nice.10', '2006-07-13 08:14:15.000000', NULL, 1),
(2617996, 360130, 61679, '<td valign="top">These are very difficult lighting conditions to shoot under.  The exposure for the sky is well done; however, the back lighting makes the main object look flat.  The sharpest focus on the main object appears to be at the top of the image where it meets the clouds.  The bright clouds makes it very difficult to look there for any length of time, which sends my eye back to the lower half of the structure which is not as sharp in focus.</td>', 'These are very difficult lighting conditions to shoot under.  The exposure for the sky is well done; however, the back lighting makes the main object look flat.  The sharpest focus on the main object appears to be at the top of the image where it meets the clouds.  The bright clouds makes it very difficult to look there for any length of time, which sends my eye back to the lower half of the structure which is not as sharp in focus.', '2006-07-13 08:14:37.000000', NULL, 1),
(2617997, 362067, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:14:38.000000', NULL, 1),
(2617999, 361876, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:15:02.000000', NULL, 1),
(2618000, 361064, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:15:35.000000', NULL, 1),
(2618001, 362143, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:15:50.000000', NULL, 1),
(2618003, 362071, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:16:48.000000', NULL, 1),
(2618004, 361607, 25654, '<td valign="top">Nice Perspective . 8.</td>', 'Nice Perspective . 8.', '2006-07-13 08:17:01.000000', NULL, 1),
(2618006, 360790, 61679, '<td valign="top">I think this image could have benefited from a smaller apperature to increase the depth of focus.  You might want to try using a square crop to eliminate the negative space on the left and to increase the effectiveness of the angle of the main subject and lines of the pine needles.</td>', 'I think this image could have benefited from a smaller apperature to increase the depth of focus.  You might want to try using a square crop to eliminate the negative space on the left and to increase the effectiveness of the angle of the main subject and lines of the pine needles.', '2006-07-13 08:18:24.000000', NULL, 1),
(2618012, 360813, 61679, '<td valign="top">The silhouette is well exectuted and lines of the power cables help keep the viewers eyes in the photo.  The sky however, lacks any features which add to the image and you might want to consider cropping out the tree on the right so it doesn''t compete with the main subject.</td>', 'The silhouette is well exectuted and lines of the power cables help keep the viewers eyes in the photo.  The sky however, lacks any features which add to the image and you might want to consider cropping out the tree on the right so it doesn''t compete with the main subject.', '2006-07-13 08:21:42.000000', NULL, 1),
(2618019, 361853, 61679, '<td valign="top">The perspective of this image is very interesting and the symmetry of the image works very well.  The image could use a bit of sharpening and if you would have taken this shot from just a bit lower perspective, you might have prevented the blown highlights on top of the markers.</td>', 'The perspective of this image is very interesting and the symmetry of the image works very well.  The image could use a bit of sharpening and if you would have taken this shot from just a bit lower perspective, you might have prevented the blown highlights on top of the markers.', '2006-07-13 08:24:33.000000', NULL, 1),
(2618024, 362382, 61679, '<td valign="top">I''m sure others will tell you that the image is small and that you need to make sure your entries use the complete pixel size allowed by dpc.  It is really hard to tell how good this image is at its present size but I do like the illumination on the leaves.</td>', 'I''m sure others will tell you that the image is small and that you need to make sure your entries use the complete pixel size allowed by dpc.  It is really hard to tell how good this image is at its present size but I do like the illumination on the leaves.', '2006-07-13 08:26:53.000000', NULL, 1),
(2618037, 361692, 61679, '<td valign="top">The perspective you choose is one I wish I had access to but I have a couple of suggestions you might want to try to improve the image.  First, move slightly to the right to center the bridge in the view finder.  This will eliminate the perception that the bridge is tipping to the right and ready to fall over.  Second, use a smaller apperature to increase the depth of focus, thus improving the sharpness of the buildings in the background.</td>', 'The perspective you choose is one I wish I had access to but I have a couple of suggestions you might want to try to improve the image.  First, move slightly to the right to center the bridge in the view finder.  This will eliminate the perception that the bridge is tipping to the right and ready to fall over.  Second, use a smaller apperature to increase the depth of focus, thus improving the sharpness of the buildings in the background.', '2006-07-13 08:29:53.000000', NULL, 1),
(2618045, 361071, 61679, '<td valign="top">Any interesting perspective to say the least.  The white balance could use a little tweaking to improve the color.  Btw, thanks for flushing first.</td>', 'Any interesting perspective to say the least.  The white balance could use a little tweaking to improve the color.  Btw, thanks for flushing first.', '2006-07-13 08:31:27.000000', NULL, 1),
(2618052, 362230, 61679, '<td valign="top">I really think the perspective of this image is more interesting without the 90 degree rotation.</td>', 'I really think the perspective of this image is more interesting without the 90 degree rotation.', '2006-07-13 08:32:32.000000', NULL, 1),
(2618063, 362371, 61679, '<td valign="top">You did a nice job balancing the exposure between the building and the sky.  I think your score is going to suffer a little because of all of the buildings entered in this challenge.  You might want to play around with USM to see if you can get the details in the building to pop a little more.  If you have USM available in your software, try Radius 50, Amount 20%, and Threshold 0 and see what it does.  You may need to adjust the brightness afterwards.</td>', 'You did a nice job balancing the exposure between the building and the sky.  I think your score is going to suffer a little because of all of the buildings entered in this challenge.  You might want to play around with USM to see if you can get the details in the building to pop a little more.  If you have USM available in your software, try Radius 50, Amount 20%, and Threshold 0 and see what it does.  You may need to adjust the brightness afterwards.', '2006-07-13 08:37:44.000000', NULL, 1),
(2618077, 362438, 61679, '<td valign="top">This shot is not as easy to take as some people might think.  To shoot straight up and get the net centered is very difficult.  If you could have suspended the ball over the net, this picture would have had a bit more interest to it.</td>', 'This shot is not as easy to take as some people might think.  To shoot straight up and get the net centered is very difficult.  If you could have suspended the ball over the net, this picture would have had a bit more interest to it.', '2006-07-13 08:40:25.000000', NULL, 1),
(2618087, 361991, 61679, '<td valign="top">An interesting perspective shooting up through a beverage can at a mouth.  The concept could have been improved if the mouth were in focus.</td>', 'An interesting perspective shooting up through a beverage can at a mouth.  The concept could have been improved if the mouth were in focus.', '2006-07-13 08:42:24.000000', NULL, 1),
(2618098, 361728, 61679, '<td valign="top">Actually, this is a big house and small river and the perspective you used does make it seem to be opposite of reality.  For this image to be more sucessful the foreground needs to be in better focus.  You might also want to play around and increase the saturation a bit and maybe adjust the colors to tone down the yellows and bring up the greens.</td>', 'Actually, this is a big house and small river and the perspective you used does make it seem to be opposite of reality.  For this image to be more sucessful the foreground needs to be in better focus.  You might also want to play around and increase the saturation a bit and maybe adjust the colors to tone down the yellows and bring up the greens.', '2006-07-13 08:45:32.000000', NULL, 1),
(2618104, 360325, 61679, '<td valign="top">A rare perspectie indeed; however the image suffers from being out of focus.  You also might want to consider cropping this to make it a horizontal image, as the negative space to the right of the moon is much more attractive and effective than the space above the moon.</td>', 'A rare perspectie indeed; however the image suffers from being out of focus.  You also might want to consider cropping this to make it a horizontal image, as the negative space to the right of the moon is much more attractive and effective than the space above the moon.', '2006-07-13 08:47:18.000000', NULL, 1),
(2618110, 360831, 61679, '<td valign="top">The lighting of this image makes the focus seem out of balance.  There is tremendous detail in the foreground; however, the light background draws the veiwers eyes to the silhouette of the people, which lack sharpness.</td>', 'The lighting of this image makes the focus seem out of balance.  There is tremendous detail in the foreground; however, the light background draws the veiwers eyes to the silhouette of the people, which lack sharpness.', '2006-07-13 08:49:34.000000', NULL, 1),
(2618118, 362338, 27482, '<td valign="top">I normally am a sucker for slanted shots but this one is putting me off for some reason, like it was just slanted to fit this challenge, not because it looks cooler or better because it is slanted.  Anyway, not a bad shot at all, just something off about it.</td>', 'I normally am a sucker for slanted shots but this one is putting me off for some reason, like it was just slanted to fit this challenge, not because it looks cooler or better because it is slanted.  Anyway, not a bad shot at all, just something off about it.', '2006-07-13 08:51:49.000000', NULL, 1),
(2618122, 361529, 61679, '<td valign="top">My son would love a hand painter board like these.  If you crop the right side of the image to remove about a third of the painter, I think you will find that the boards become a stronger focal point in the image and the perspective you are trying to show will become stronger as well.</td>', 'My son would love a hand painter board like these.  If you crop the right side of the image to remove about a third of the painter, I think you will find that the boards become a stronger focal point in the image and the perspective you are trying to show will become stronger as well.', '2006-07-13 08:52:45.000000', NULL, 1),
