(2626777, 360736, 60862, '<td valign="top">Nice.</td>', 'Nice.', '2006-07-16 12:46:32.000000', NULL, 1),
(2626778, 360747, 60862, '<td valign="top">I see what you''re trying to do, but it doesn''t convey that to me.  Maybe from a lower angle, with their heads actually in the clouds?</td>', 'I see what you''re trying to do, but it doesn''t convey that to me.  Maybe from a lower angle, with their heads actually in the clouds?', '2006-07-16 12:47:03.000000', NULL, 1),
