(2626792, 362460, 60862, '<td valign="top">Interesting concept, nice execution.</td>', 'Interesting concept, nice execution.', '2006-07-16 12:54:46.000000', NULL, 1),
(2626794, 362126, 60862, '<td valign="top">I tend to prefer slightly angled shots over dead center.  It lets you see the distant items better.  But nice shot anyway.</td>', 'I tend to prefer slightly angled shots over dead center.  It lets you see the distant items better.  But nice shot anyway.', '2006-07-16 12:55:28.000000', NULL, 1),
(2626795, 362369, 60862, '<td valign="top">Beautiful shot, but othe than the angle from the bottom to the mid-right side, there''s nothing drawing me into the distance.</td>', 'Beautiful shot, but othe than the angle from the bottom to the mid-right side, there''s nothing drawing me into the distance.', '2006-07-16 12:56:21.000000', NULL, 1),
(2626797, 362535, 60862, '<td valign="top">Not seeing how this conveys perspective.</td>', 'Not seeing how this conveys perspective.', '2006-07-16 12:56:34.000000', NULL, 1),
