(2626808, 360171, 60862, '<td valign="top">Really not getting the point.  Maybe your notes will explain?<br/> <br/>Also, this is mighty close to the literal interpretation DQ criterion.  I suppose by having two items you qualify.</td>', 'Really not getting the point.  Maybe your notes will explain? Also, this is mighty close to the literal interpretation DQ criterion.  I suppose by having two items you qualify.', '2006-07-16 13:02:51.000000', NULL, 1),
(2626813, 362219, 60862, '<td valign="top">Interesting perspective.</td>', 'Interesting perspective.', '2006-07-16 13:04:31.000000', NULL, 1),
