(2630125, 360782, 56696, '<td valign="top">ok.</td>', 'ok.', '2006-07-17 14:31:11.000000', NULL, 1),
(2630245, 359917, 54885, '<td valign="top">i gave this a 10 because this has such great potential-this appears to be cropped too much( maybe get a diff. angle on the barn with more of the barn showing)  -maybe sharpen and add a fill light, and if possible increase sat. just a little; but otherwise this is just wonderful and thank you for sharing such a wonderful view</td>', 'i gave this a 10 because this has such great potential-this appears to be cropped too much( maybe get a diff. angle on the barn with more of the barn showing)  -maybe sharpen and add a fill light, and if possible increase sat. just a little; but otherwise this is just wonderful and thank you for sharing such a wonderful view', '2006-07-17 15:09:54.000000', NULL, 1),
(2630290, 360130, 54885, '<td valign="top">this is a very good idea but the picture seems to be out of focus- the lighting is excellent and i love the angle of this shot.</td>', 'this is a very good idea but the picture seems to be out of focus- the lighting is excellent and i love the angle of this shot.', '2006-07-17 15:25:01.000000', NULL, 1),
